"""Market-neutral supplemental cold-start seeds for FactorEngine v2 operators."""
from __future__ import annotations
from .model import ColdStartFactor


def _row(market,name,formula,family,subfamily,tier="core",horizon=20):
    return ColdStartFactor(
        factor_id=f"{market}_v2_{name.lower()}",market=market,surface="extended",formula=formula,
        family=family,subfamily=subfamily,horizon=horizon,complexity="moderate",availability_tier=tier,
        rationale=f"Production cold-start coverage for {name}.",direction_hint="unknown",
        metadata={"source":"v2_operator_seeds","operator":name},
    )


def v2_operator_seeds(market:str):
    rows=[]
    def add(name,formula,family="technical_structure",sub="v2",tier="core",h=20):rows.append(_row(market,name,formula,family,sub,tier,h))
